ALTER TABLE public.order_stops ADD COLUMN IF NOT EXISTS delay_responsibility text GENERATED ALWAYS AS (
CASE delay_reason
    WHEN 'vehicle_breakdown'::text THEN 'us'::text
    WHEN 'driver_hours'::text THEN 'us'::text
    WHEN 'planning_error'::text THEN 'us'::text
    WHEN 'previous_stop'::text THEN 'us'::text
    WHEN 'cargo_not_ready'::text THEN 'client'::text
    WHEN 'loading_wait'::text THEN 'client'::text
    WHEN 'order_change'::text THEN 'client'::text
    WHEN 'missing_docs'::text THEN 'client'::text
    WHEN 'unloading_wait'::text THEN 'consignee'::text
    WHEN 'closed_refused'::text THEN 'consignee'::text
    WHEN 'border_queue'::text THEN 'borders'::text
    WHEN 'customs'::text THEN 'borders'::text
    WHEN 'traffic'::text THEN 'external'::text
    WHEN 'weather'::text THEN 'external'::text
    WHEN 'ferry_train'::text THEN 'external'::text
    WHEN 'strike_roads'::text THEN 'external'::text
    WHEN 'other'::text THEN 'other'::text
    ELSE NULL::text
END) STORED;
