CREATE OR REPLACE FUNCTION public.ct_setting(p_key text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$ select value from ct_settings where key = p_key $function$
;
CREATE OR REPLACE FUNCTION public.order_pallets(o orders)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
    select coalesce(o.loading_pallets_1, 0) + coalesce(o.loading_pallets_2, 0) + coalesce(o.loading_pallets_3, 0)
         + coalesce(o.loading_pallets_4, 0) + coalesce(o.loading_pallets_5, 0) + coalesce(o.loading_pallets_6, 0)
         + coalesce(o.loading_pallets_7, 0) + coalesce(o.loading_pallets_8, 0) + coalesce(o.loading_pallets_9, 0)
         + coalesce(o.loading_pallets_10, 0)
  $function$
;
CREATE OR REPLACE FUNCTION public.stock_natl_delivered(p_status text, p_delivery date)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
    select coalesce(p_status = 'Delivered' or (p_status is distinct from 'Cancelled' and p_delivery <= current_date), false)
  $function$
;
CREATE OR REPLACE FUNCTION public.stock_vs_charge(p_x numeric, p_piece_pallets numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
  declare
    v_f numeric;
  begin
    if p_piece_pallets is null then
      return p_x;
    end if;
    v_f := public.ct_setting('full_truck_pallets');
    if v_f is null then
      raise exception 'ct_settings.full_truck_pallets is missing — the Veroia Switch charge of a stock piece cannot be prorated (057, OWNER-Q3)';
    end if;
    return round(p_x * least(p_piece_pallets, v_f) / v_f, 2);
  end
  $function$
;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.stock_v_pieces')) = 'r' THEN EXECUTE 'DROP TABLE public.stock_v_pieces'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.stock_v_lots')) = 'r' THEN EXECUTE 'DROP TABLE public.stock_v_lots'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.stock_v_lot_money')) = 'r' THEN EXECUTE 'DROP TABLE public.stock_v_lot_money'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.stock_v_lot_alloc')) = 'r' THEN EXECUTE 'DROP TABLE public.stock_v_lot_alloc'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.stock_v_rt_amounts')) = 'r' THEN EXECUTE 'DROP TABLE public.stock_v_rt_amounts'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.ct_v_wear_rate')) = 'r' THEN EXECUTE 'DROP TABLE public.ct_v_wear_rate'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.ct_v_rt_revenue')) = 'r' THEN EXECUTE 'DROP TABLE public.ct_v_rt_revenue'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.ct_v_rt_costs')) = 'r' THEN EXECUTE 'DROP TABLE public.ct_v_rt_costs'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.ct_v_rt_pnl')) = 'r' THEN EXECUTE 'DROP TABLE public.ct_v_rt_pnl'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.dl_v_rt_route')) = 'r' THEN EXECUTE 'DROP TABLE public.dl_v_rt_route'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.dl_v_rt_gap')) = 'r' THEN EXECUTE 'DROP TABLE public.dl_v_rt_gap'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.dl_v_entries')) = 'r' THEN EXECUTE 'DROP TABLE public.dl_v_entries'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.dl_v_balance')) = 'r' THEN EXECUTE 'DROP TABLE public.dl_v_balance'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.ct_v_rt_pallet_gate')) = 'r' THEN EXECUTE 'DROP TABLE public.ct_v_rt_pallet_gate'; END IF; END $d$;
DO $d$ BEGIN IF (SELECT relkind FROM pg_class WHERE oid = to_regclass('public.pl_v_order_gate')) = 'r' THEN EXECUTE 'DROP TABLE public.pl_v_order_gate'; END IF; END $d$;
CREATE OR REPLACE VIEW public.stock_v_pieces AS  SELECT o.stock_lot_id AS lot_id,
    'intl'::text AS piece_kind,
    o.id AS piece_id,
    o.legacy_id AS piece_rec,
    o.client_id,
    o.loading_location_1_id AS pickup_location_id,
    order_pallets(o.*) AS pallets,
    o.status,
    o.loading_datetime AS loading_date,
    COALESCE(o.status = 'Delivered'::text, false) AS delivered,
        CASE
            WHEN o.status = 'Delivered'::text THEN COALESCE(o.actual_delivery_date, o.delivery_datetime)
            ELSE NULL::date
        END AS delivered_on,
    o.truck_id IS NOT NULL OR o.partner_id IS NOT NULL AS on_truck,
    o.created_at
   FROM orders o
  WHERE o.deleted_at IS NULL AND o.stock_lot_id IS NOT NULL
UNION ALL
 SELECT n.stock_lot_id AS lot_id,
    'natl'::text AS piece_kind,
    n.id AS piece_id,
    n.legacy_id AS piece_rec,
    n.client_id,
    n.pickup_location_1_id AS pickup_location_id,
    COALESCE(n.pallets, 0::numeric) AS pallets,
    n.status,
    n.loading_datetime AS loading_date,
    stock_natl_delivered(n.status, n.delivery_datetime) AS delivered,
        CASE
            WHEN stock_natl_delivered(n.status, n.delivery_datetime) THEN COALESCE(n.actual_delivery_date, n.delivery_datetime)
            ELSE NULL::date
        END AS delivered_on,
    n.truck_id IS NOT NULL OR n.partner_id IS NOT NULL AS on_truck,
    n.created_at
   FROM national_orders n
  WHERE n.deleted_at IS NULL AND n.stock_lot_id IS NOT NULL;
CREATE OR REPLACE VIEW public.stock_v_lots AS  SELECT b.id,
    b.legacy_id,
    b.deleted_at,
    b.order_id,
    b.nat_order_id,
    b.lot_no,
    b.source_kind,
    b.reference,
    b.source_notes,
    b.client_id,
    b.client_rec,
    b.client_name,
    b.warehouse_location_id,
    b.warehouse_rec,
    b.warehouse_name,
    b.warehouse_city,
    b.warehouse_country,
    b.intake_partner_id,
    b.intake_status,
    b.intake_delivered,
    b.received_on,
    b.ops_status,
    b.stock_pallets,
    b.drawn_pallets,
    b.remaining_pallets,
    b.delivered_pallets,
        CASE
            WHEN b.closed_at IS NOT NULL THEN GREATEST(b.remaining_pallets, 0::numeric)
            ELSE 0::numeric
        END AS written_off_pallets,
    b.pieces,
    b.pieces_delivered,
    b.pieces_without_truck,
        CASE
            WHEN b.intake_delivered THEN 0::bigint
            ELSE b.pieces_left
        END AS pieces_moving,
    b.last_piece_delivered,
    b.closed_note,
    b.closed_at,
    k.complete,
        CASE
            WHEN k.complete THEN GREATEST(b.received_on, b.last_piece_delivered, (b.closed_at AT TIME ZONE 'Europe/Athens'::text)::date)
            ELSE NULL::date
        END AS completed_on,
    b.invoiced
   FROM ( SELECT s.id,
            s.legacy_id,
            s.deleted_at,
            s.order_id,
            s.nat_order_id,
            COALESCE(s.order_id, s.nat_order_id) AS lot_no,
            src.source_kind,
            src.reference,
            src.source_notes,
            src.client_id,
            c.legacy_id AS client_rec,
            c.company_name AS client_name,
            src.warehouse_location_id,
            w.legacy_id AS warehouse_rec,
            w.name AS warehouse_name,
            w.city AS warehouse_city,
            w.country AS warehouse_country,
            src.intake_partner_id,
            src.intake_status,
            src.intake_delivered,
                CASE
                    WHEN src.intake_delivered THEN src.delivered_date
                    ELSE NULL::date
                END AS received_on,
            src.ops_status,
            src.stock_pallets,
            pc.drawn_pallets,
            src.stock_pallets - pc.drawn_pallets AS remaining_pallets,
            pc.delivered_pallets,
            pc.pieces,
            pc.pieces_delivered,
            pc.pieces_without_truck,
            pc.pieces_left,
            pc.last_piece_delivered,
            s.closed_note,
            s.closed_at,
            src.invoiced
           FROM stock_lots s
             JOIN LATERAL ( SELECT 'intl'::text AS source_kind,
                    o.reference,
                    o.notes AS source_notes,
                    o.client_id,
                    o.unloading_location_1_id AS warehouse_location_id,
                    o.partner_id AS intake_partner_id,
                    o.status AS intake_status,
                    COALESCE(o.status = 'Delivered'::text, false) AS intake_delivered,
                    COALESCE(o.actual_delivery_date, o.delivery_datetime) AS delivered_date,
                    o.ops_status,
                    order_pallets(o.*) AS stock_pallets,
                    COALESCE(o.invoiced, false) AS invoiced
                   FROM orders o
                  WHERE o.id = s.order_id AND o.deleted_at IS NULL
                UNION ALL
                 SELECT 'natl'::text AS text,
                    n.reference,
                    n.notes,
                    n.client_id,
                    n.delivery_location_1_id,
                    n.partner_id,
                    n.status,
                    stock_natl_delivered(n.status, n.delivery_datetime) AS stock_natl_delivered,
                    COALESCE(n.actual_delivery_date, n.delivery_datetime) AS "coalesce",
                    n.ops_status,
                    COALESCE(n.pallets, 0::numeric) AS "coalesce",
                    COALESCE(n.invoiced, false) AS "coalesce"
                   FROM national_orders n
                  WHERE n.id = s.nat_order_id AND n.deleted_at IS NULL) src ON true
             CROSS JOIN LATERAL ( SELECT count(*) AS pieces,
                    count(*) FILTER (WHERE p.delivered) AS pieces_delivered,
                    count(*) FILTER (WHERE NOT p.on_truck AND NOT p.delivered) AS pieces_without_truck,
                    count(*) FILTER (WHERE (p.status = 'In Transit'::text OR p.delivered) AND p.loading_date < CURRENT_DATE) AS pieces_left,
                    COALESCE(sum(p.pallets), 0::numeric) AS drawn_pallets,
                    COALESCE(sum(p.pallets) FILTER (WHERE p.delivered), 0::numeric) AS delivered_pallets,
                    max(p.delivered_on) AS last_piece_delivered
                   FROM stock_v_pieces p
                  WHERE p.lot_id = s.id) pc
             LEFT JOIN clients c ON c.id = src.client_id
             LEFT JOIN locations w ON w.id = src.warehouse_location_id
          WHERE s.deleted_at IS NULL) b
     CROSS JOIN LATERAL ( SELECT COALESCE(b.intake_delivered AND b.pieces = b.pieces_delivered AND (b.remaining_pallets = 0::numeric OR b.closed_at IS NOT NULL), false) AS complete) k;
CREATE OR REPLACE VIEW public.stock_v_lot_money AS  SELECT l.id AS lot_id,
    l.legacy_id AS lot_rec,
    l.source_kind,
    l.lot_no AS source_id,
    x.source_rec,
    x.price,
    x.partner_cost,
    x.has_assignment,
    s.warehouse_charge,
    c.charge_total,
        CASE
            WHEN k.st = 'ok'::text THEN k.net
            ELSE NULL::numeric
        END AS net,
    l.stock_pallets AS total_pallets,
        CASE
            WHEN k.st = 'ok'::text THEN round(k.net / NULLIF(l.stock_pallets, 0::numeric), 4)
            ELSE NULL::numeric
        END AS per_pallet,
    l.drawn_pallets,
        CASE
            WHEN k.st = 'ok'::text THEN k.alloc
            ELSE NULL::numeric
        END AS allocated_amount,
    l.remaining_pallets,
        CASE
            WHEN k.st = 'ok'::text THEN
            CASE
                WHEN l.closed_at IS NULL THEN k.net - k.alloc
                ELSE 0.00
            END
            ELSE NULL::numeric
        END AS in_stock_amount,
    l.written_off_pallets,
        CASE
            WHEN k.st = 'ok'::text THEN
            CASE
                WHEN l.closed_at IS NOT NULL THEN k.net - k.alloc
                ELSE 0.00
            END
            ELSE NULL::numeric
        END AS written_off_amount,
    l.closed_at,
    k.st AS allocation_status
   FROM stock_v_lots l
     JOIN stock_lots s ON s.id = l.id
     CROSS JOIN LATERAL ( SELECT o.legacy_id AS source_rec,
            o.price,
            pa.partner_rate AS partner_cost,
            pa.id IS NOT NULL AS has_assignment
           FROM orders o
             LEFT JOIN LATERAL ( SELECT pa_1.id,
                    pa_1.partner_rate
                   FROM partner_assignments pa_1
                  WHERE pa_1.order_id = o.id AND pa_1.deleted_at IS NULL AND pa_1.status <> 'Cancelled'::text
                  ORDER BY pa_1.id DESC
                 LIMIT 1) pa ON true
          WHERE o.id = l.order_id
        UNION ALL
         SELECT n.legacy_id,
            n.price,
            NULL::numeric AS "numeric",
            false
           FROM national_orders n
          WHERE n.id = l.nat_order_id) x
     CROSS JOIN LATERAL ( SELECT
                CASE
                    WHEN x.has_assignment AND x.partner_cost IS NULL THEN NULL::numeric
                    WHEN x.partner_cost IS NULL AND s.warehouse_charge IS NULL THEN NULL::numeric
                    ELSE COALESCE(x.partner_cost, 0::numeric) + COALESCE(s.warehouse_charge, 0::numeric)
                END AS charge_total) c
     CROSS JOIN LATERAL ( SELECT
                CASE
                    WHEN COALESCE(x.price, 0::numeric) <= 0::numeric THEN 'no_price'::text
                    WHEN x.has_assignment AND x.partner_cost IS NULL THEN 'no_partner_rate'::text
                    WHEN c.charge_total IS NULL THEN 'no_charge'::text
                    WHEN l.stock_pallets <= 0::numeric THEN 'no_pallets'::text
                    ELSE 'ok'::text
                END AS st,
            round(x.price - c.charge_total, 2) AS net,
            round(round(x.price - c.charge_total, 2) * l.drawn_pallets / NULLIF(l.stock_pallets, 0::numeric), 2) AS alloc) k;
CREATE OR REPLACE VIEW public.stock_v_lot_alloc AS  SELECT lot_id,
    lot_rec,
    piece_kind,
    piece_id,
    piece_rec,
    seq,
    pallets,
    cum_pallets,
        CASE
            WHEN allocation_status = 'ok'::text THEN round(net * cum_pallets / total_pallets, 2) - round(net * (cum_pallets - pallets) / total_pallets, 2)
            ELSE NULL::numeric
        END AS amount
   FROM ( SELECT p.lot_id,
            m.lot_rec,
            p.piece_kind,
            p.piece_id,
            p.piece_rec,
            p.pallets,
            row_number() OVER (PARTITION BY p.lot_id ORDER BY p.created_at, p.piece_kind, p.piece_id) AS seq,
            sum(p.pallets) OVER (PARTITION BY p.lot_id ORDER BY p.created_at, p.piece_kind, p.piece_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_pallets,
            m.allocation_status,
            m.net,
            m.total_pallets
           FROM stock_v_pieces p
             JOIN stock_v_lot_money m ON m.lot_id = p.lot_id) w;
CREATE OR REPLACE VIEW public.stock_v_rt_amounts AS  SELECT m.source_id AS order_id,
    COALESCE(m.partner_cost, 0::numeric) AS rt_amount
   FROM stock_v_lot_money m
  WHERE m.source_kind = 'intl'::text AND m.allocation_status = 'ok'::text
UNION ALL
 SELECT a.piece_id AS order_id,
    a.amount AS rt_amount
   FROM stock_v_lot_alloc a
     JOIN stock_v_lot_money m ON m.lot_id = a.lot_id
  WHERE a.piece_kind = 'intl'::text AND m.source_kind = 'intl'::text AND m.allocation_status = 'ok'::text;
CREATE OR REPLACE VIEW public.ct_v_wear_rate WITH (security_invoker=true) AS  WITH m AS (
         SELECT maint_history.truck_id,
            sum(maint_history.cost) AS maint_cost
           FROM maint_history
          WHERE maint_history.truck_id IS NOT NULL AND maint_history.deleted_at IS NULL AND maint_history.service_date >= (CURRENT_DATE - '1 year'::interval)
          GROUP BY maint_history.truck_id
        ), k AS (
         SELECT ct_round_trips.truck_id,
            sum(ct_round_trips.total_km) AS km
           FROM ct_round_trips
          WHERE ct_round_trips.truck_id IS NOT NULL AND ct_round_trips.status <> 'cancelled'::text AND ct_round_trips.date_start >= (CURRENT_DATE - '1 year'::interval)
          GROUP BY ct_round_trips.truck_id
        )
 SELECT t.id AS truck_id,
        CASE
            WHEN COALESCE(k.km, 0::bigint) > 0 AND m.maint_cost IS NOT NULL THEN round(m.maint_cost / k.km::numeric, 4)
            ELSE ct_setting('wear_fallback_eur_km'::text)
        END AS eur_per_km
   FROM trucks t
     LEFT JOIN m ON m.truck_id = t.id
     LEFT JOIN k ON k.truck_id = t.id;
CREATE OR REPLACE VIEW public.ct_v_rt_revenue AS  WITH natord_home AS (
         SELECT nord.id AS national_order_id,
            nord.price,
            COALESCE(( SELECT min(h1.id) AS min
                   FROM national_loads h1
                  WHERE h1.source_national_order_id = nord.id AND h1.deleted_at IS NULL), ( SELECT min(h2.id) AS min
                   FROM national_loads h2
                  WHERE h2.deleted_at IS NULL AND h2.source_cons_load_id = (( SELECT gl.cons_load_id
                           FROM groupage_lines gl
                          WHERE gl.national_order_id = nord.id AND gl.deleted_at IS NULL AND gl.cons_load_id IS NOT NULL
                          ORDER BY gl.id
                         LIMIT 1)))) AS home_nat_load_id
           FROM national_orders nord
          WHERE nord.deleted_at IS NULL AND nord.price IS NOT NULL AND nord.source_order_id IS NULL
        ), legs AS (
         SELECT rt.id AS rt_id,
                CASE
                    WHEN l.order_id IS NOT NULL THEN COALESCE(sa.rt_amount, o.price,
                    CASE
                        WHEN o.leg_no = 1 THEN p.price
                        ELSE NULL::numeric
                    END, 0::numeric) -
                    CASE
                        WHEN
                        CASE
                            WHEN o.parent_order_id IS NOT NULL THEN p.veroia_switch
                            ELSE o.veroia_switch
                        END THEN stock_vs_charge(
                        CASE
                            WHEN
                            CASE
                                WHEN o.parent_order_id IS NOT NULL THEN p.direction
                                ELSE o.direction
                            END = 'Export'::text THEN ct_setting('x_export'::text)
                            ELSE ct_setting('x_import'::text)
                        END, vp.pallets)
                        ELSE 0::numeric
                    END
                    ELSE 0::numeric
                END AS rev_intl,
                CASE
                    WHEN l.nat_load_id IS NOT NULL THEN
                    CASE
                        WHEN nl.source_type = 'Direct'::text AND nl.source_order_id IS NOT NULL AND nl.id = (( SELECT min(d.id) AS min
                           FROM national_loads d
                          WHERE d.source_order_id = nl.source_order_id AND d.source_type = 'Direct'::text AND d.deleted_at IS NULL)) AND
                        CASE
                            WHEN so.parent_order_id IS NOT NULL THEN sp.veroia_switch
                            ELSE so.veroia_switch
                        END THEN stock_vs_charge(
                        CASE
                            WHEN
                            CASE
                                WHEN so.parent_order_id IS NOT NULL THEN sp.direction
                                ELSE so.direction
                            END = 'Export'::text THEN ct_setting('x_export'::text)
                            ELSE ct_setting('x_import'::text)
                        END, svp.pallets)
                        ELSE 0::numeric
                    END + COALESCE(( SELECT sum(h.price) AS sum
                       FROM natord_home h
                      WHERE h.home_nat_load_id = nl.id), 0::numeric)
                    ELSE 0::numeric
                END AS rev_natl
           FROM ct_round_trips rt
             LEFT JOIN ct_rt_legs l ON l.rt_id = rt.id
             LEFT JOIN orders o ON o.id = l.order_id
             LEFT JOIN orders p ON p.id = o.parent_order_id
             LEFT JOIN stock_v_rt_amounts sa ON sa.order_id = o.id
             LEFT JOIN stock_v_pieces vp ON vp.piece_kind = 'intl'::text AND vp.piece_id = o.id
             LEFT JOIN national_loads nl ON nl.id = l.nat_load_id
             LEFT JOIN orders so ON so.id = nl.source_order_id
             LEFT JOIN orders sp ON sp.id = so.parent_order_id
             LEFT JOIN stock_v_pieces svp ON svp.piece_kind = 'intl'::text AND svp.piece_id = so.id
        )
 SELECT rt_id,
    COALESCE(sum(rev_intl + rev_natl), 0::numeric) AS revenue,
    COALESCE(sum(rev_intl), 0::numeric) AS revenue_intl,
    COALESCE(sum(rev_natl), 0::numeric) AS revenue_natl
   FROM legs
  GROUP BY rt_id;
CREATE OR REPLACE VIEW public.ct_v_rt_costs AS  WITH lines AS (
         SELECT ct_cost_lines.rt_id,
            sum(ct_cost_lines.net) FILTER (WHERE ct_cost_lines.category <> 'partner_rate'::text) AS net_other,
            sum(ct_cost_lines.vat) AS vat,
            sum(ct_cost_lines.net) FILTER (WHERE ct_cost_lines.category = 'partner_rate'::text) AS partner_invoiced
           FROM ct_cost_lines
          WHERE ct_cost_lines.rt_id IS NOT NULL
          GROUP BY ct_cost_lines.rt_id
        ), carried AS (
         SELECT l.rt_id,
            o.id AS order_id
           FROM ct_rt_legs l
             JOIN orders o ON o.id = l.order_id
        UNION
         SELECT l.rt_id,
            s.id
           FROM ct_rt_legs l
             JOIN orders o ON o.id = l.order_id AND o.parent_order_id IS NOT NULL
             JOIN orders s ON s.parent_order_id = o.parent_order_id AND s.id <> o.id AND s.deleted_at IS NULL AND s.partner_id IS NOT NULL
          WHERE NOT (EXISTS ( SELECT 1
                   FROM ct_rt_legs l2
                     JOIN ct_round_trips r2 ON r2.id = l2.rt_id
                  WHERE l2.order_id = s.id AND r2.status <> 'cancelled'::text))
        ), planned AS (
         SELECT x.rt_id,
            sum(x.partner_rate) AS partner_planned
           FROM ( SELECT c.rt_id,
                    pa.partner_rate
                   FROM carried c
                     JOIN LATERAL ( SELECT pa_1.partner_rate
                           FROM partner_assignments pa_1
                          WHERE pa_1.order_id = c.order_id AND pa_1.deleted_at IS NULL AND pa_1.status <> 'Cancelled'::text
                          ORDER BY pa_1.id DESC
                         LIMIT 1) pa ON true
                UNION ALL
                 SELECT l.rt_id,
                    nl.partner_rate
                   FROM ct_rt_legs l
                     JOIN national_loads nl ON nl.id = l.nat_load_id
                  WHERE nl.deleted_at IS NULL AND COALESCE(nl.is_partner_trip, false) AND nl.partner_rate IS NOT NULL) x
          GROUP BY x.rt_id
        )
 SELECT rt.id AS rt_id,
    COALESCE(li.net_other, 0::numeric) + COALESCE(NULLIF(li.partner_invoiced, 0::numeric), pl.partner_planned, 0::numeric) + COALESCE(dl.trip_value, 0::numeric) + COALESCE(dl.expenses, 0::numeric) AS lines_net,
    COALESCE(li.vat, 0::numeric) AS vat,
        CASE
            WHEN rt.trip_type = 'OWNED'::text AND rt.total_km IS NOT NULL THEN round(COALESCE(w.eur_per_km, ct_setting('wear_fallback_eur_km'::text)) * rt.total_km::numeric, 2)
            ELSE 0::numeric
        END AS wear,
    dl.trip_value AS dl_trip_value,
    dl.expenses AS dl_expenses,
    dl.id IS NOT NULL AND dl.trip_value IS NULL AS driver_pay_pending,
    rt.trip_type = 'OWNED'::text AND rt.driver_id IS NOT NULL AND dl.id IS NULL AS driver_pay_missing,
    COALESCE(pl.partner_planned, 0::numeric) AS partner_planned,
    COALESCE(li.partner_invoiced, 0::numeric) AS partner_invoiced
   FROM ct_round_trips rt
     LEFT JOIN lines li ON li.rt_id = rt.id
     LEFT JOIN planned pl ON pl.rt_id = rt.id
     LEFT JOIN dl_entries dl ON dl.rt_id = rt.id AND dl.deleted_at IS NULL
     LEFT JOIN ct_v_wear_rate w ON w.truck_id = rt.truck_id;
CREATE OR REPLACE VIEW public.ct_v_rt_pnl AS  SELECT rt.id,
    rt.code,
    rt.scope,
    rt.trip_type,
    rt.truck_id,
    rt.driver_id,
    rt.partner_id,
    rt.date_start,
    rt.date_end,
    rt.status,
    rt.total_km,
    r.revenue,
    c.lines_net + c.wear AS cost_net,
    c.vat AS cost_vat,
    c.lines_net + c.wear + c.vat AS cost_gross,
    r.revenue - (c.lines_net + c.wear + c.vat) AS profit_worst,
    r.revenue - (c.lines_net + c.wear) AS profit_ex_vat,
        CASE
            WHEN r.revenue > 0::numeric THEN round((r.revenue - (c.lines_net + c.wear + c.vat)) / r.revenue * 100::numeric, 1)
            ELSE NULL::numeric
        END AS margin_worst_pct,
        CASE
            WHEN r.revenue > 0::numeric THEN round((r.revenue - (c.lines_net + c.wear)) / r.revenue * 100::numeric, 1)
            ELSE NULL::numeric
        END AS margin_ex_vat_pct,
    c.dl_trip_value,
    c.dl_expenses,
    c.driver_pay_pending,
    c.driver_pay_missing,
    c.partner_planned,
    c.partner_invoiced,
    r.revenue_intl,
    r.revenue_natl
   FROM ct_round_trips rt
     JOIN ct_v_rt_revenue r ON r.rt_id = rt.id
     JOIN ct_v_rt_costs c ON c.rt_id = rt.id
  WHERE rt.status <> 'cancelled'::text;
CREATE OR REPLACE VIEW public.dl_v_rt_route WITH (security_invoker=true) AS  WITH leg AS (
         SELECT l.rt_id,
            l.id AS leg_id,
            l.direction,
            l.seq,
            COALESCE(o.loading_datetime::timestamp with time zone, nl.loading_datetime)::date AS load_d,
            COALESCE(o.actual_delivery_date, nl.actual_delivery_date, o.delivery_datetime, nl.delivery_datetime::date) AS deliv_d,
            COALESCE(o.loading_location_1_id, nl.pickup_location_1_id) AS from_id,
            COALESCE(o.unloading_location_10_id, o.unloading_location_9_id, o.unloading_location_8_id, o.unloading_location_7_id, o.unloading_location_6_id, o.unloading_location_5_id, o.unloading_location_4_id, o.unloading_location_3_id, o.unloading_location_2_id, o.unloading_location_1_id, nl.delivery_location_10_id, nl.delivery_location_9_id, nl.delivery_location_8_id, nl.delivery_location_7_id, nl.delivery_location_6_id, nl.delivery_location_5_id, nl.delivery_location_4_id, nl.delivery_location_3_id, nl.delivery_location_2_id, nl.delivery_location_1_id) AS to_id,
            ( SELECT count(*) AS count
                   FROM ( VALUES (o.loading_location_2_id), (o.loading_location_3_id), (o.loading_location_4_id), (o.loading_location_5_id), (o.loading_location_6_id), (o.loading_location_7_id), (o.loading_location_8_id), (o.loading_location_9_id), (o.loading_location_10_id), (o.unloading_location_2_id), (o.unloading_location_3_id), (o.unloading_location_4_id), (o.unloading_location_5_id), (o.unloading_location_6_id), (o.unloading_location_7_id), (o.unloading_location_8_id), (o.unloading_location_9_id), (o.unloading_location_10_id), (nl.pickup_location_2_id), (nl.pickup_location_3_id), (nl.pickup_location_4_id), (nl.pickup_location_5_id), (nl.pickup_location_6_id), (nl.pickup_location_7_id), (nl.pickup_location_8_id), (nl.pickup_location_9_id), (nl.pickup_location_10_id), (nl.delivery_location_2_id), (nl.delivery_location_3_id), (nl.delivery_location_4_id), (nl.delivery_location_5_id), (nl.delivery_location_6_id), (nl.delivery_location_7_id), (nl.delivery_location_8_id), (nl.delivery_location_9_id), (nl.delivery_location_10_id)) v(x)
                  WHERE v.x IS NOT NULL) AS extra_stops
           FROM ct_rt_legs l
             LEFT JOIN orders o ON o.id = l.order_id
             LEFT JOIN national_loads nl ON nl.id = l.nat_load_id
        )
 SELECT leg.rt_id,
    string_agg((COALESCE(lf.city, lf.name) || ' → '::text) || COALESCE(lt.city, lt.name), ' · '::text ORDER BY leg.seq, leg.load_d, leg.leg_id) AS route_text,
    jsonb_agg(jsonb_build_object('dir', leg.direction, 'load', leg.load_d, 'deliv', leg.deliv_d, 'from', jsonb_build_object('name', lf.name, 'city', lf.city, 'country', lf.country), 'to', jsonb_build_object('name', lt.name, 'city', lt.city, 'country', lt.country), 'extra_stops', leg.extra_stops) ORDER BY leg.seq, leg.load_d, leg.leg_id) AS route_legs
   FROM leg
     LEFT JOIN locations lf ON lf.id = leg.from_id
     LEFT JOIN locations lt ON lt.id = leg.to_id
  GROUP BY leg.rt_id;
CREATE OR REPLACE VIEW public.dl_v_rt_gap WITH (security_invoker=true) AS  SELECT id AS rt_id,
    code,
    driver_id,
    date_start
   FROM ct_round_trips rt
  WHERE trip_type = 'OWNED'::text AND driver_id IS NOT NULL AND status <> 'cancelled'::text AND NOT (EXISTS ( SELECT 1
           FROM dl_entries e
          WHERE e.rt_id = rt.id AND e.deleted_at IS NULL));
CREATE OR REPLACE VIEW public.dl_v_entries WITH (security_invoker=true) AS  SELECT e.id,
    e.driver_id,
    e.entry_type,
    e.entry_date,
    e.date_end,
    e.rt_id,
    rt.code AS rt_code,
    COALESCE(e.route, rr.route_text, rt.code) AS route_text,
    e.trip_value,
    e.advance,
    e.expenses,
    e.amount,
    e.balance_delta,
    e.source,
    e.import_batch,
    e.needs_review,
    e.review_note,
    e.note,
    e.deleted_at,
    e.deleted_reason,
    e.created_by,
    e.created_at,
    e.updated_at,
    e.deleted_at IS NOT NULL AS cancelled,
    e.entry_type = 'trip'::text AND e.trip_value IS NULL AND e.deleted_at IS NULL AS pending,
    sum(
        CASE
            WHEN e.deleted_at IS NULL THEN e.balance_delta
            ELSE 0::numeric
        END) OVER (PARTITION BY e.driver_id ORDER BY e.entry_date, e.id ROWS UNBOUNDED PRECEDING) AS running_balance,
        CASE
            WHEN e.route IS NULL THEN rr.route_legs
            ELSE NULL::jsonb
        END AS route_legs,
    COALESCE(c.n, 0::bigint)::integer AS cash_lines,
    COALESCE(c.s, 0::numeric) AS cash_sum,
    e.expenses_auto,
    e.local_move_id,
        CASE
            WHEN e.local_move_id IS NOT NULL THEN lr.info
            ELSE rl.info
        END AS relay_info
   FROM dl_entries e
     LEFT JOIN ct_round_trips rt ON rt.id = e.rt_id
     LEFT JOIN dl_v_rt_route rr ON rr.rt_id = e.rt_id
     LEFT JOIN LATERAL ( SELECT count(*) AS n,
            sum(l.net + COALESCE(l.vat, 0::numeric)) AS s
           FROM ct_cost_lines l
          WHERE l.rt_id = e.rt_id AND l.pay_source = 'CASH'::text) c ON e.rt_id IS NOT NULL
     LEFT JOIN LATERAL ( SELECT jsonb_build_object('kind', 'local_day', 'moves', COALESCE(jsonb_agg(jsonb_build_object('id', lm.id, 'move_kind', lm.move_kind, 'order_id', lm.parent_order_id, 'rt_codes', ( SELECT COALESCE(jsonb_agg(r2.code ORDER BY r2.id), '[]'::jsonb) AS "coalesce"
                   FROM ct_rt_legs l2
                     JOIN ct_round_trips r2 ON r2.id = l2.rt_id AND r2.status <> 'cancelled'::text
                  WHERE l2.order_id = lm.parent_order_id)) ORDER BY lm.id), '[]'::jsonb)) AS info
           FROM local_moves lm
          WHERE lm.driver_id = e.driver_id AND lm.move_date = e.entry_date AND lm.move_kind <> 'local'::text AND lm.deleted_at IS NULL AND lm.status <> 'Cancelled'::text) lr ON e.local_move_id IS NOT NULL AND e.deleted_at IS NULL
     LEFT JOIN LATERAL ( SELECT jsonb_build_object('kind', 'rt', 'relays', jsonb_agg(jsonb_build_object('id', lm.id, 'move_kind', lm.move_kind, 'order_id', lm.parent_order_id, 'driver_id', lm.driver_id, 'driver_name', d.full_name, 'move_date', lm.move_date) ORDER BY lm.id)) AS info
           FROM ct_rt_legs l3
             JOIN local_moves lm ON lm.parent_order_id = l3.order_id AND lm.move_kind <> 'local'::text AND lm.deleted_at IS NULL AND lm.status <> 'Cancelled'::text
             LEFT JOIN drivers d ON d.id = lm.driver_id
          WHERE l3.rt_id = e.rt_id
         HAVING count(*) > 0) rl ON e.rt_id IS NOT NULL;
CREATE OR REPLACE VIEW public.dl_v_balance WITH (security_invoker=true) AS  WITH live AS (
         SELECT dl_entries.id,
            dl_entries.driver_id,
            dl_entries.entry_type,
            dl_entries.entry_date,
            dl_entries.date_end,
            dl_entries.route,
            dl_entries.rt_id,
            dl_entries.trip_value,
            dl_entries.advance,
            dl_entries.expenses,
            dl_entries.amount,
            dl_entries.balance_delta,
            dl_entries.source,
            dl_entries.import_batch,
            dl_entries.needs_review,
            dl_entries.review_note,
            dl_entries.note,
            dl_entries.deleted_at,
            dl_entries.deleted_reason,
            dl_entries.created_by,
            dl_entries.created_at,
            dl_entries.updated_at
           FROM dl_entries
          WHERE dl_entries.deleted_at IS NULL
        ), last_trip AS (
         SELECT DISTINCT ON (live.driver_id) live.driver_id,
            live.entry_date,
            live.date_end,
            live.rt_id,
            live.route
           FROM live
          WHERE live.entry_type = 'trip'::text
          ORDER BY live.driver_id, live.entry_date DESC, live.id DESC
        ), last_pay AS (
         SELECT DISTINCT ON (live.driver_id) live.driver_id,
            live.entry_date,
            live.entry_type
           FROM live
          WHERE live.entry_type = ANY (ARRAY['payment_cash'::text, 'payment_bank'::text])
          ORDER BY live.driver_id, live.entry_date DESC, live.id DESC
        ), agg AS (
         SELECT live.driver_id,
            sum(live.balance_delta) AS balance,
            count(*) FILTER (WHERE live.entry_type = 'trip'::text AND live.entry_date >= date_trunc('year'::text, CURRENT_DATE::timestamp with time zone)) AS trips_ytd,
            count(*) FILTER (WHERE live.entry_type = 'trip'::text AND live.trip_value IS NULL) AS pending_count,
            count(*) FILTER (WHERE live.needs_review) AS review_count,
            max(live.entry_date) AS last_entry_date
           FROM live
          GROUP BY live.driver_id
        )
 SELECT d.id AS driver_id,
    d.full_name,
    d.type,
    d.active,
    COALESCE(a.balance, 0::numeric) AS balance,
    a.driver_id IS NOT NULL AS has_entries,
    COALESCE(a.trips_ytd, 0::bigint) AS trips_ytd,
    COALESCE(a.pending_count, 0::bigint) AS pending_count,
    COALESCE(a.review_count, 0::bigint) AS review_count,
    a.last_entry_date,
    CURRENT_DATE - a.last_entry_date AS days_since_last_entry,
    lt.entry_date AS last_trip_date,
    lt.date_end AS last_trip_end,
    COALESCE(lt.route, rr.route_text, rt.code) AS last_trip_route,
    rt.code AS last_trip_rt_code,
    lp.entry_date AS last_payment_date,
    lp.entry_type AS last_payment_type
   FROM drivers d
     LEFT JOIN agg a ON a.driver_id = d.id
     LEFT JOIN last_trip lt ON lt.driver_id = d.id
     LEFT JOIN ct_round_trips rt ON rt.id = lt.rt_id
     LEFT JOIN dl_v_rt_route rr ON rr.rt_id = lt.rt_id
     LEFT JOIN last_pay lp ON lp.driver_id = d.id
  WHERE d.deleted_at IS NULL;
CREATE OR REPLACE VIEW public.ct_v_rt_pallet_gate WITH (security_invoker=true) AS  WITH rt_orders AS (
         SELECT l.rt_id,
            l.order_id
           FROM ct_rt_legs l
             JOIN orders o ON o.id = l.order_id AND o.deleted_at IS NULL
          WHERE l.order_id IS NOT NULL AND o.pallet_exchange = true
        ), sheets AS (
         SELECT DISTINCT pl_movements.order_id
           FROM pl_movements
          WHERE pl_movements.status = 'confirmed'::text AND (pl_movements.event_type = ANY (ARRAY['PARTNER_PICKUP'::text, 'PARTNER_DROPOFF'::text])) AND pl_movements.order_id IS NOT NULL
        )
 SELECT ro.rt_id,
    count(*) AS legs_needing_sheet,
    count(s.order_id) AS legs_with_sheet,
    count(*) = count(s.order_id) AS sheets_ok
   FROM rt_orders ro
     LEFT JOIN sheets s ON s.order_id = ro.order_id
  GROUP BY ro.rt_id;
CREATE OR REPLACE VIEW public.pl_v_order_gate WITH (security_invoker=true) AS  WITH ls AS (
         SELECT s.order_id,
            s.id AS stop_id
           FROM order_stops s
          WHERE s.stop_type = 'Loading'::text AND s.order_id IS NOT NULL AND s.deleted_at IS NULL
        ), cov AS (
         SELECT DISTINCT pl_movements.order_stop_id
           FROM pl_movements
          WHERE pl_movements.event_type = 'LOADING'::text AND pl_movements.status = 'confirmed'::text AND pl_movements.order_stop_id IS NOT NULL
        )
 SELECT o.legacy_id AS order_rec,
    ls.order_id,
    count(*) AS loading_stops,
    count(cov.order_stop_id) AS covered_stops,
    count(*) = count(cov.order_stop_id) AS sheets_ok
   FROM ls
     JOIN orders o ON o.id = ls.order_id AND o.deleted_at IS NULL
     LEFT JOIN cov ON cov.order_stop_id = ls.stop_id
  GROUP BY o.legacy_id, ls.order_id;
